    N, M, K = map(int, input().split())
    special_nodes = set(map(int, input().split()))
    graph = defaultdict(dict)
    for _ in range(M):
        x, y, z = map(int, input().split())
        graph[x][y] = z
        graph[y][x] = z

    shortest_distances = {node: float('inf') for node in special_nodes}
    shortest_distances[1] = 0

    pq = [(0, 1)]
    while pq:
        distance, node = heapq.heappop(pq)
        if distance > shortest_distances[node]:
            continue
        for neighbor, weight in graph[node].items():
            new_distance = distance + weight
            if new_distance < shortest_distances[neighbor]:
                shortest_distances[neighbor] = new_distance
                heapq.heappush(pq, (new_distance, neighbor))

    min_distance = float('inf')
    for node in special_nodes:
        for other_node in special_nodes:
            if node == other_node:
                continue
            min_distance = min(min_distance, shortest_distances[node] + shortest_distances[other_node])

    print(min_distance)

if __name__ == "__main__":
